const PUBLIC_PAGES = new Set(['/','/beta','/source','/trust','/blog','/testing','/feedback','/security','/brand','/roadmap','/privacy','/terms']);
const SHOP_PATHS = new Set(['/phones','/phones/terms','/phones/privacy','/phones/thanks','/phones.css','/phones-promotion.css',PHONE_LAUNCH_PATH]);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function paymentLink(value) {
  try { const u = new URL(value); return u.origin === 'https://buy.stripe.com' && !u.username && !u.password && !u.search && !u.hash && /^\/[A-Za-z0-9_]+$/.test(u.pathname) ? u.href : null; }
  catch { return null; }
}
function validatedSeller(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const text = (input, max) => typeof input === 'string' && input.trim().length > 0 && input.trim().length <= max && !/[\u0000-\u001f\u007f]/.test(input) ? input.trim() : null;
  const name = text(value.name, 120);
  if (!name || !Array.isArray(value.addressLines) || value.addressLines.length < 2 || value.addressLines.length > 6) return null;
  const addressLines = value.addressLines.map(line => text(line, 160));
  if (addressLines.some(line => !line)) return null;
  let phone;
  if (value.phone !== undefined) {
    phone = text(value.phone, 40);
    if (!phone || !/^[+()0-9 .-]+$/.test(phone)) return null;
  }
  return {name, addressLines, ...(phone ? {phone} : {})};
}
function resolveSeller(config, env) {
  // Read only the explicitly designated public business-contact binding.
  // Never infer a seller address from account-owner or other environment data.
  const raw = env?.PHONE_SHOP_SELLER_JSON;
  if (typeof raw === 'string' && raw.length <= 2000) {
    try { const seller = validatedSeller(JSON.parse(raw)); if (seller) return seller; }
    catch { /* Invalid runtime configuration falls back only to explicit supplied seller details. */ }
  }
  return validatedSeller(config.seller);
}
