function seoMarkup(title, description, path, schema) {
  const url=CANONICAL_ORIGIN+path,image=CANONICAL_ORIGIN+PHONE_SOCIAL_IMAGE;
  const graph=schema.length ? JSON.stringify({'@context':'https://schema.org','@graph':schema}).replace(/[<>&\u2028\u2029]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0')) : '';
  return `<meta property="og:site_name" content="Vellivex"><meta property="og:locale" content="en_GB"><meta property="og:type" content="${path===PHONE_LAUNCH_PATH?'article':'website'}"><meta property="og:title" content="${escape(title)} | Vellivex"><meta property="og:description" content="${escape(description)}"><meta property="og:url" content="${url}"><meta property="og:image" content="${image}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Vellivex Privacy Phones — new and refurbished Pixel 9a with GrapheneOS"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escape(title)} | Vellivex"><meta name="twitter:description" content="${escape(description)}"><meta name="twitter:image" content="${image}"><meta name="twitter:image:alt" content="Vellivex Privacy Phones — new and refurbished Pixel 9a with GrapheneOS">${path===PHONE_LAUNCH_PATH?'<meta property="article:published_time" content="2026-11-12"><meta property="article:modified_time" content="2026-11-12">':''}${graph?'<script id="vellivex-phone-schema" type="application/ld+json">'+graph+'</script>':''}`;
}

