export const PHONE_PROMOTION_CSS = '#vellivex-phone-promotion{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-top:24px;padding:18px 23px;border:1px solid #34596c;background:#122638;border-radius:6px}#vellivex-phone-promotion p{font-size:12px;line-height:1.7;margin:3px 0 0}#vellivex-phone-promotion strong{font-size:14px;font-weight:600}#vellivex-phone-promotion .text-link{font-size:12px;white-space:nowrap;color:#a5e5ed}@media(max-width:700px){#vellivex-phone-promotion{display:block;padding:17px 19px;margin-top:18px}#vellivex-phone-promotion .text-link{margin-top:12px}}';

async function shopResponse(body, request, type = 'text/html; charset=utf-8', status = 200) {
  const headers = {...envelope, 'Content-Type':type, 'X-Vellivex-Phone-Shop':'2026-11-12'};
  if (new URL(request.url).pathname.replace(/\/$/,'') === '/phones/thanks') headers['X-Robots-Tag'] = 'noindex, nofollow';
  if (type.startsWith('text/html')) {
    const jsonLd = body.match(/<script id="vellivex-phone-schema" type="application\/ld\+json">([^]*?)<\/script>/)?.[1];
    if (jsonLd) {
      const hash = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(jsonLd)));
      headers['Content-Security-Policy'] += "; script-src 'sha256-" + btoa(String.fromCharCode(...hash)) + "'";
    }
  }
  return new Response(request.method === 'HEAD' ? null : body, {status, headers});
}

export function withPhoneShop(worker, config = {}) {
  if (typeof worker?.fetch !== 'function') throw new TypeError('An existing Worker is required');
  return {...worker, async fetch(request, env, ctx) {
    const url = new URL(request.url), path = url.pathname.replace(/\/$/,'') || '/';
    if (!ORIGINS.has(url.origin)) return worker.fetch(request, env, ctx);
    const media = phoneMediaResponse(request);
    if (media) return media;
    if (SHOP_PATHS.has(path)) {
      if (!['GET','HEAD'].includes(request.method)) return new Response('Method not allowed', {status:405, headers:{...envelope, 'Allow':'GET, HEAD','Content-Type':'text/plain; charset=utf-8'}});
      if (path === '/phones.css') return shopResponse(PHONE_SHOP_CSS, request, 'text/css; charset=utf-8');
      if (path === '/phones-promotion.css') return shopResponse(PHONE_PROMOTION_CSS, request, 'text/css; charset=utf-8');
      const viewConfig = {...config, seller:resolveSeller(config, env)};
      const body = path === '/phones/terms' ? terms(viewConfig) : path === '/phones/privacy' ? privacy(viewConfig) : path === '/phones/thanks' ? thanks() : path === PHONE_LAUNCH_PATH ? launchArticle() : catalogue(viewConfig);
      return shopResponse(body, request);
    }
    const response = await worker.fetch(request, env, ctx);
    if (request.method === 'GET' && path === '/robots.txt' && response.status === 200 && response.headers.get('Content-Type')?.includes('text/plain')) {
      const original = await response.text();
      const lines = original.split(/\r?\n/);
      let star = -1;
      for (let i=0;i<lines.length;i++) if (/^User-agent:\s*\*\s*$/i.test(lines[i])) { star=i; break; }
      // A wildcard may share a rule group with other User-agent records. Leave
      // those groups intact instead of inserting rules between their headers.
      let sharedGroup = false;
      if (star >= 0) for (const step of [-1,1]) {
        for (let i=star+step;i>=0 && i<lines.length;i+=step) {
          const line=lines[i].trim();
          if (!line || line.startsWith('#')) continue;
          if (/^User-agent:/i.test(line)) sharedGroup=true;
          break;
        }
      }
      if (star >= 0 && !sharedGroup) {
        let end = star+1;
        while (end<lines.length && !/^User-agent:/i.test(lines[end])) end++;
        const group=lines.slice(star+1,end);
        const additions=['/phones','/media/vellivex-privacy-phones',PHONE_PRODUCT_IMAGE].filter(value=>!group.some(line=>line.replace(/^Allow:\s*/i,'').trim()===value && /^Allow:/i.test(line))).map(value=>'Allow: '+value);
        if (additions.length) lines.splice(star+1,0,...additions);
      }
      const headers = new Headers(response.headers);
      for (const h of ['Content-Length','Content-Encoding','ETag','Last-Modified','Content-MD5','Digest']) headers.delete(h);
      headers.set('Cache-Control','no-store');
      return new Response(lines.join('\n'), {status:response.status, statusText:response.statusText, headers});
    }
    if (request.method === 'GET' && path === '/sitemap.xml' && response.status === 200 && response.headers.get('Content-Type')?.includes('xml')) {
      let body = await response.text();
      if (body.includes('</urlset>')) for (const route of ['/phones','/phones/terms','/phones/privacy',PHONE_LAUNCH_PATH]) {
        const loc = 'https://www.vellivex.com' + route;
        if (!body.includes('<loc>' + loc + '</loc>')) body = body.replace('</urlset>', '<url><loc>' + loc + '</loc></url></urlset>');
      }
      const headers = new Headers(response.headers);
      for (const h of ['Content-Length','Content-Encoding','ETag','Last-Modified','Content-MD5','Digest']) headers.delete(h);
      headers.set('Cache-Control','no-store');
      return new Response(body, {status:response.status, statusText:response.statusText, headers});
    }
    if (request.method !== 'GET' || !PUBLIC_PAGES.has(path) || response.status !== 200 || !response.headers.get('Content-Type')?.includes('text/html')) return response;
    let body = await response.text();
    // Only the established public navigation is extended. App documents and auth responses never enter this branch.
    body = body.replace(/<nav\b([^>]*)\bid=(['"])navigation\2([^>]*)>([\s\S]*?)<\/nav>/i, (full, before, quote, after, content) => content.includes('data-phone-shop-link') ? full : `<nav${before}id=${quote}navigation${quote}${after}><a href="/phones" data-phone-shop-link>Privacy phones</a>${content}</nav>`);
    if (path === '/' && !body.includes('id="vellivex-phone-promotion"')) {
      const promo = '<section id="vellivex-phone-promotion" class="wrap" aria-label="Vellivex privacy phones"><div><strong>Meet your Vellivex Privacy Phone.</strong><p>New & refurbished Pixel 9a · GrapheneOS · From £375 · UK delivery in two weeks</p></div><a class="text-link" href="/phones">Shop privacy phones ↗</a></section>';
      body = body.replace(/<main\b[^>]*>/i, opening => opening + promo);
      body = body.replace('</head>', '<link rel="stylesheet" href="/phones-promotion.css"></head>');
    }
    if (path === '/blog' && !body.includes('id="vellivex-phone-launch-post"')) {
      const card = `<article class="product" id="vellivex-phone-launch-post"><span class="tag">Privacy phones · Buying guide</span><h2><a href="${PHONE_LAUNCH_PATH}">GrapheneOS privacy phones in the UK</a></h2><p>Meet the new and refurbished Vellivex Pixel 9a. Understand the software, encrypted messaging, customer-owned keys and two-week UK delivery.</p><p class="fine">Vellivex · 12 November 2026</p><a class="text-link" href="${PHONE_LAUNCH_PATH}">Read the buying guide ↗</a></article>`;
      body = body.replace(/<section\b([^>]*)class=(["'])([^"']*\bproducts\b[^"']*)\2([^>]*)>/i, opening => opening + card);
    }
    const headers = new Headers(response.headers);
    for (const h of ['Content-Length','Content-Encoding','ETag','Last-Modified','Content-MD5','Digest']) headers.delete(h);
    headers.set('Cache-Control','no-store');
    return new Response(body, {status:response.status, statusText:response.statusText, headers});
  }};
}
